package com.kodebytes.acasado.analytics.config;
import static org.assertj.core.api.Assertions.assertThat; import com.kodebytes.acasado.analytics.fraud.FraudRulesEngine; import com.kodebytes.acasado.analytics.model.*;
import java.math.BigDecimal; import java.time.*; import java.util.Properties; import org.apache.kafka.common.serialization.Serdes; import org.apache.kafka.streams.*; import org.junit.jupiter.api.*; import org.springframework.kafka.support.serializer.JsonSerde;
class PaymentAnalyticsTopologyTest {
 private TopologyTestDriver driver; private TestInputTopic<String,PaymentEvent> payments; private TestInputTopic<String,MerchantRisk> risks; private TestOutputTopic<String,EnrichedPayment> enriched,alerts; private TestOutputTopic<String,AccountPaymentMetric> metrics;
 @BeforeEach void setUp(){var p=new PaymentStreamsProperties("payments","risks","enriched","alerts","metrics",Duration.ofMinutes(5),Duration.ofMinutes(1)); var b=new StreamsBuilder(); new PaymentAnalyticsTopology().paymentStream(b,p,new FraudRulesEngine()); var c=new Properties(); c.put(StreamsConfig.APPLICATION_ID_CONFIG,"test"); c.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG,"dummy:9092"); driver=new TopologyTestDriver(b.build(),c); payments=driver.createInputTopic("payments",Serdes.String().serializer(),new JsonSerde<>(PaymentEvent.class).serializer()); risks=driver.createInputTopic("risks",Serdes.String().serializer(),new JsonSerde<>(MerchantRisk.class).serializer()); enriched=driver.createOutputTopic("enriched",Serdes.String().deserializer(),new JsonSerde<>(EnrichedPayment.class).deserializer()); alerts=driver.createOutputTopic("alerts",Serdes.String().deserializer(),new JsonSerde<>(EnrichedPayment.class).deserializer()); metrics=driver.createOutputTopic("metrics",Serdes.String().deserializer(),new JsonSerde<>(AccountPaymentMetric.class).deserializer());}
 @AfterEach void close(){driver.close();}
 @Test void enrichesFlagsAndAggregates(){Instant t=Instant.parse("2026-09-14T10:01:00Z"); risks.pipeInput("m1",new MerchantRisk("m1",95,false,t),t); payments.pipeInput("p1",new PaymentEvent("1","p1","a1","m1",new BigDecimal("12000"),"CHF","CH",t),t); var result=enriched.readValue(); assertThat(result.fraudulent()).isTrue(); assertThat(result.fraudReasons()).contains("HIGH_VALUE","HIGH_RISK_MERCHANT"); assertThat(alerts.readValue().paymentId()).isEqualTo("p1"); assertThat(metrics.readValue().paymentCount()).isEqualTo(1);}
}